from collections import Counter,defaultdict

def fq(path):
    out=[]
    with open(path) as f:
        rec=[]
        for i,line in enumerate(f):
            rec.append(line.strip())
            if len(rec)==4:
                out.append(tuple(rec)); rec=[]
    return out
D={n:fq(f'exogenous.mix.reads.q1.{n}.fq') for n in ['mix','exo','endo']}
for a in D:
    for b in D:
        if a<b:
